// LogModelValues replaces the values pool — for a subject whose
// accepted values a raw draw cannot spell. The pool feeds every value slot,
// the sequences and the laws alike; keep its draws colliding, because values
// that never revisit a key pass every comparison over a history that holds
// nothing twice.
func LogModelValues(values *model.Generator[causalchain.Entry]) LogModelOption {
	return func(c *logModelConfig) { c.values = values }
}

// logModelOnlyLaw narrows the run to one law.
//
// Unexported: this is the saturation prover's instrument, not a knob. A
// conformance run asserts every law the classifications earned, and dropping
// all but one is only ever right when the question is "can this law fail",
// which is the one question the prover asks.
//
// Without it the prover cannot answer that question at all. The runner stops
// the iteration at the first law that fails, so a defect worn for law A is
// reported under whichever law happens to catch it first — the corpus showed
// 114 such runs, each one a law that looked unsaturatable because a sibling
// spoke over it.
func logModelOnlyLaw(id string) LogModelOption {
	return func(c *logModelConfig) { c.onlyLaw = id }
}

type logModelConfig struct {
	reference func() causalchain.Log
	onlyLaw   string
	entryID   func(causalchain.Entry) string
	dependsOn func(causalchain.Entry) []string
	values    *model.Generator[causalchain.Entry]
}

func newLogModelConfig(opts ...LogModelOption) *logModelConfig {
	c := &logModelConfig{}
	for _, o := range opts {
		o(c)
	}
	return c
}

